// 1. Extract payload from Webhook
const body = $input.first().json.body || $input.first().json;

// 2. Extract inputs with defaults
const repairType = body.quiz?.repair_type || 'cosmetic';
const propertyType = body.quiz?.property_type || 'new';
const areaM2 = Number(body.quiz?.area_m2) || 50;
const addons = Array.isArray(body.quiz?.addons) ? body.quiz.addons : [];

// 3. Tariffs & Calculation Matrix
const baseRates = {
  cosmetic: 2500,
  capital: 5000,
  designer: 8500
};
const rateTitles = {
  cosmetic: 'Косметичний (2 500 грн/м²)',
  capital: 'Капітальний (5 000 грн/м²)',
  designer: 'Дизайнерський (8 500 грн/м²)'
};

const propMultipliers = {
  new: 1.0,
  secondary: 1.25
};
const propTitles = {
  new: 'Новобудова (x1.0)',
  secondary: 'Вторинне житло (x1.25)'
};

const addonPrices = {
  design_project: { title: 'Дизайн-проєкт', price: 15000 },
  electric_plumbing: { title: 'Сантехніка та електрика', price: 25000 },
  materials_delivery: { title: 'Закупівля та доставка матеріалів', price: 8000 }
};

const baseRate = baseRates[repairType] || 2500;
const multiplier = propMultipliers[propertyType] || 1.0;

let addonsTotal = 0;
const addonsNames = [];
addons.forEach(key => {
  if (addonPrices[key]) {
    addonsTotal += addonPrices[key].price;
    addonsNames.push(`${addonPrices[key].title} (+${addonPrices[key].price.toLocaleString('uk-UA')} грн)`);
  }
});

const baseCost = Math.round(areaM2 * baseRate * multiplier);
const totalAmount = baseCost + addonsTotal;

// 4. Client & Contact Metadata
const userId = body.user?.id ? String(body.user.id) : '';
const username = body.user?.username ? `@${body.user.username}` : 'Немає юзернейма';
const clientName = body.contact?.name || body.user?.first_name || 'Гість';
const clientPhone = body.contact?.phone || 'Не вказано';

// Kyiv Timestamp
const now = new Date();
const timestamp = now.toLocaleString('uk-UA', { timeZone: 'Europe/Kyiv' });

return [{
  json: {
    timestamp,
    userId,
    username,
    clientName,
    clientPhone,
    repairTypeTitle: rateTitles[repairType] || repairType,
    propertyTypeTitle: propTitles[propertyType] || propertyType,
    areaM2,
    addonsTitles: addonsNames.length > 0 ? addonsNames.join(', ') : 'Без додаткових опцій',
    baseCost,
    addonsTotal,
    totalAmount,
    totalFormatted: totalAmount.toLocaleString('uk-UA') + ' грн',
    status: 'Новий лід'
  }
}];

