// Parse callback query data: e.g. status:in_progress:+380501234567
const cb = $input.first().json.callback_query;
const parts = (cb?.data || '').split(':');
const statusCode = parts[1] || 'in_progress';
const clientPhone = parts[2] || '';

const statusTitles = {
  in_progress: '📞 Взяв у роботу',
  measuring: '📐 Призначено замір',
  deal: '🤝 Укладено договір',
  rejected: '❌ Відхилено'
};

const newStatusText = statusTitles[statusCode] || statusCode;
const adminName = cb?.from?.first_name || 'Адмін';
const originalText = cb?.message?.text || '';
const messageId = cb?.message?.message_id;
const chatId = cb?.message?.chat?.id;
const callbackId = cb?.id;

const now = new Date();
const timeStr = now.toLocaleTimeString('uk-UA', { timeZone: 'Europe/Kyiv', hour: '2-digit', minute: '2-digit' });

return [{
  json: {
    callbackId,
    chatId,
    messageId,
    clientPhone,
    newStatusText,
    adminName,
    timeStr,
    updatedCardText: originalText + `\n\n⚡ <b>ОНОВЛЕННЯ:</b> ${newStatusText}\n👤 <b>Обробив:</b> ${adminName} о ${timeStr}`
  }
}];
